#include <iostream>
using namespace std;

int main()
{
    const int SECS_PER_HOUR = 3600;
    const int SECS_PER_MIN = 60;
    int total = 98765;

    int hours = total / SECS_PER_HOUR;
    int left = total % SECS_PER_HOUR;
    int minutes = left / SECS_PER_MIN;
    int seconds = left % SECS_PER_MIN;

    cout << hours << " hours, " << minutes << " minutes, "
         << seconds << " seconds" << endl;
    return 0;
}

