#include <iostream>
#include <iomanip>
using namespace std;

int main()
{
    const double TAX_RATE = 0.07;
    const double TIP_RATE = 0.18;
    double meal;

    cin >> meal;
    double tax = meal * TAX_RATE;
    double tip = meal * TIP_RATE;
    double total = meal + tax + tip;

    cout << fixed << setprecision(2);
    cout << left << setw(8) << "Meal" << right << setw(8) << meal << endl;
    cout << left << setw(8) << "Tax" << right << setw(8) << tax << endl;
    cout << left << setw(8) << "Tip" << right << setw(8) << tip << endl;
    cout << left << setw(8) << "Total" << right << setw(8) << total << endl;
    return 0;
}

