#include <iostream>
#include <iomanip>
#include <cmath>
using namespace std;

int main()
{
    const double PI = 3.14159265;
    double r;
    cin >> r;

    double area = PI * r * r;
    double circ = 2 * PI * r;

    cout << fixed << setprecision(2);
    cout << "Area: " << area << endl;
    cout << "Circumference: " << circ << endl;
    cout << "Remainder: " << fmod(area, 4) << endl;
    cout << setprecision(0);
    cout << "Floor: " << floor(area) << endl;
    cout << "Ceil: " << ceil(area) << endl;
    return 0;
}
